// src/data/LevelData.ts
// Hand-crafted level definitions for the Bayonetta-inspired roguelike.
// Each level has a tile map (40 wide Ã— 25 tall), enemy placements, item placements,
// decorations, and metadata.
//
// Tile Legend:
//   0 = Floor (walkable)
//   1 = Wall (stone)
//   2 = Pillar (destructible)
//   3 = Water/Pit (hazard)
//   4 = Lava (damage)
//   5 = Stairs/Exit
//   6 = Door (locked)
//   7 = Chest location
//   8 = Spawn point
//   9 = Boss spawn

export interface SectionExit {
  /** Tile coords of the door */
  x: number;
  y: number;
  /** Index of the target section */
  to: number;
  /** Where the player appears in the target section (tile coords) */
  spawnX: number;
  spawnY: number;
}

export interface EnemyPlacement {
  type: string;
  x: number;
  y: number;
  level: number;
  patrol?: { x: number; y: number }[];
  dropTable?: { itemId: string; chance: number }[];
}

export interface ItemPlacement {
  type: string;
  x: number;
  y: number;
  quantity?: number;
}

export interface DecorationPlacement {
  type: string;
  x: number;
  y: number;
  scale?: number;
  rotation?: number;
  tint?: number;
}

export interface LevelDefinition {
  id: string;
  name: string;
  description: string;
  theme: 'gothic_cathedral' | 'inferno_pit' | 'celestial_tower' | 'venetian_streets' |
         'roman_ruins' | 'paradiso_garden' | 'witches_crypt' | 'clocktower' |
         'colosseum' | 'limbo_void';
  music: string;
  ambientColor: number;
  fogColor: number;
  fogDensity: number;
  lightIntensity: number;
  tileMap: number[][];
  enemies: EnemyPlacement[];
  items: ItemPlacement[];
  decorations: DecorationPlacement[];
  exits?: SectionExit[];
