import type { PlayerClassDefinition } from '../../data/ClassDatabase';
import { CombatRuntime } from '../runtime/CombatRuntime';
import { CombatClass, DamageType } from '../core/types';

export interface GameCombatBridgeOptions {
  classDefinition: PlayerClassDefinition;
  seed?: string | number;
}

export class GameCombatBridge {
  public readonly runtime: CombatRuntime;
  private readonly playerId = 'game-player';
  private readonly targetId = 'game-target-proxy';
  private readonly enemyId = 'game-enemy-proxy';
  private hitSequence = 0;

  public constructor(options: GameCombatBridgeOptions) {
    const definition = options.classDefinition;
    this.runtime = new CombatRuntime(options.seed ?? 'game-combat');
    this.runtime.addCombatant({
      id: this.playerId,
      name: definition.name,
      classId: definition.id as CombatClass,
      team: 'player',
      stats: {
        maximumHealth: definition.maxHp * 100,
        maximumMana: definition.maxMagic,
        attackPower: definition.baseDamage,
        spellPower: definition.baseDamage,
        movementSpeed: definition.speed,
        armor: definition.id === 'knight' ? 24 : 8,
        resistance: definition.id === 'mage' ? 22 : 10,
        criticalChance: definition.id === 'rogue' ? 0.18 : definition.id === 'ranger' ? 0.12 : 0.08,
        criticalMultiplier: definition.id === 'rogue' ? 1.8 : 1.55,
      },
    });
    this.runtime.addCombatant({ id: this.targetId, name: 'Target Proxy', classId: 'enemy', team: 'enemy', stats: { maximumHealth: 100000, armor: 0, resistance: 0, dodgeChance: 0, blockChance: 0 } });
    this.runtime.addCombatant({ id: this.enemyId, name: 'Enemy Proxy', classId: 'enemy', team: 'enemy', stats: { maximumHealth: 100000, attackPower: 20, spellPower: 20 } });
  }

  public synchronizePlayer(health: number, maximumHealth: number, mana: number, maximumMana: number): void {
    const player = this.runtime.getCombatant(this.playerId);
    if (!player) return;
    player.stats.setBase('maximumHealth', maximumHealth * 100);
    player.stats.setBase('maximumMana', maximumMana);
    player.resources.setMaximum('health', maximumHealth * 100);
    player.resources.setMaximum('mana', maximumMana);
    player.resources.set('health', health * 100);
    player.resources.set('mana', mana);
  }

  public calculatePlayerDamage(baseAmount: number, type: DamageType, comboMultiplier = 1): number {
    const result = this.runtime.previewDamage({
      sourceId: this.playerId,
      targetId: this.targetId,
      damageType: type,
      baseAmount: baseAmount * comboMultiplier,
      powerRatio: 0,
      canCrit: true,
      canBlock: false,
      ignoresArmor: 0,
      ignoresResistance: 0,
      tags: ['game-hit', type],
      hitIndex: ++this.hitSequence,
    });
    return Math.max(0, result?.applied ?? baseAmount * comboMultiplier);
  }

  public calculateIncomingDamage(baseAmount: number, type: DamageType = 'physical'): number {
    const result = this.runtime.previewDamage({
      sourceId: this.enemyId,
      targetId: this.playerId,
      damageType: type,
      baseAmount,
      powerRatio: 0,
      canCrit: false,
      canBlock: true,
      ignoresArmor: 0,
      ignoresResistance: 0,
      tags: ['enemy-hit'],
      hitIndex: ++this.hitSequence,
    });
    return Math.max(0, result?.applied ?? baseAmount);
  }

  public advance(deltaMilliseconds: number): void { this.runtime.update(deltaMilliseconds); }
  public abilitiesForPlayer(): string[] { return this.runtime.abilities.forClass(this.runtime.getCombatant(this.playerId)?.snapshot().classId ?? 'knight').map((ability) => ability.definition.id); }
  public dispose(): void { this.runtime.dispose(); }
}

--- src/procedural/pipeline/ProceduralPipeline.ts ---
import { DeterministicRandom } from '../../simulation/core/DeterministicRandom';
import { MapRepairer } from '../analysis/MapRepairer';
import { TopologyAnalyzer } from '../analysis/TopologyAnalyzer';
import { MapValidator } from '../analysis/MapValidator';
import { DecorationPlanner } from '../content/DecorationPlanner';
import { EncounterPlanner } from '../content/EncounterPlanner';
import { LootPlanner } from '../content/LootPlanner';
import { BiomePainter } from '../terrain/BiomePainter';
import { TerrainComposer } from '../rules/TerrainComposer';
import { GenerationResult, GeneratorOptions, normalizeOptions } from '../core/types';
import { GeneratorRegistry } from './GeneratorRegistry';

export interface PipelineHooks {
  afterLayout?: (map: GenerationResult['map']) => void;
  afterTerrain?: (map: GenerationResult['map']) => void;
  afterContent?: (map: GenerationResult['map']) => void;
  afterValidation?: (result: GenerationResult) => void;
}

export class ProceduralPipeline {
  private readonly analyzer = new TopologyAnalyzer();
  private readonly validator = new MapValidator();
  private readonly repairer = new MapRepairer();
  private readonly terrain = new BiomePainter();
  private readonly terrainComposer = new TerrainComposer();
  private readonly encounters = new EncounterPlanner();
  private readonly loot = new LootPlanner();
  private readonly decorations = new DecorationPlanner();

  public constructor(private readonly registry = new GeneratorRegistry()) {}

  public generate(rawOptions: GeneratorOptions, hooks: PipelineHooks = {}): GenerationResult {
    const options = normalizeOptions(rawOptions);
    const warnings: string[] = [];
    const generator = this.registry.get(options.algorithm);
    let map = generator.generate(options);
    map.metadata.difficulty = options.difficulty;
    map.metadata.biome = options.biome;
    map.metadata.hazardDensity = options.hazardDensity;
    map.metadata.treasureDensity = options.treasureDensity;
    map.metadata.enemyDensity = options.enemyDensity;
    map.metadata.decorationDensity = options.decorationDensity;
    map.metadata.pipelineVersion = 1;
    map.metrics = this.analyzer.analyze(map);
    hooks.afterLayout?.(map);

    const random = new DeterministicRandom(options.seed).fork('procedural-pipeline');
    this.terrain.paint(map, random.fork('terrain'));
    this.terrainComposer.compose(map, random.fork('terrain-rules'));
    map.metrics = this.analyzer.analyze(map);
    hooks.afterTerrain?.(map);

    if (options.ensureConnected) {
      const early = this.validator.validate(map);
      if (!early.valid) {
        const repaired = this.repairer.repair(map);
        map = repaired.map;
        warnings.push(...repaired.repairs.map((repair) => 'reparo: ' + repair));
      }
    }
    map.metrics = this.analyzer.analyze(map);
    this.encounters.populate(map, random.fork('encounters'));
    this.loot.populate(map, random.fork('loot'));
    this.decorations.populate(map, random.fork('decorations'));
    hooks.afterContent?.(map);

    const report = this.validator.validate(map);
    map.metrics = report.metrics;
    warnings.push(...report.issues.filter((issue) => issue.severity === 'warning').map((issue) => issue.code + ': ' + issue.message));
    const result: GenerationResult = {
      map,
      warnings,
      repaired: Boolean(map.metadata.repaired),
      attempts: 1,
    };
    if (!report.valid) {
      const repaired = this.repairer.repair(map);
      result.map = repaired.map;
      result.map.metrics = this.analyzer.analyze(result.map);
      result.repaired = true;
      result.warnings.push(...repaired.repairs.map((repair) => 'reparo-final: ' + repair));
    }
    hooks.afterValidation?.(result);
    return result;
  }

  public generateBatch(options: GeneratorOptions, count: number): GenerationResult[] {
    if (!Number.isSafeInteger(count) || count < 1 || count > 100) throw new RangeError('batch count must be between 1 and 100');
    return Array.from({ length: count }, (_, index) => this.generate({ ...options, seed: String(options.seed) + ':' + index }));
  }
}

--- src/ai/navigation/NavigationService.ts ---
import { AStarPathfinder } from './AStarPathfinder';
import { NavigationGrid } from './NavigationGrid';
import { PathCache } from './PathCache';
import {
  NavCell,
  NavPoint,
  NavigationPath,
  NavigationTilePolicy,
  PathSearchOptions,
  cellKey,
} from './types';

export interface NavigationServiceOptions {
  tileSize?: number;
  cacheCapacity?: number;
  policy?: NavigationTilePolicy;
}

export class NavigationService {
  public readonly grid: NavigationGrid;
  private readonly pathfinder: AStarPathfinder;
  private readonly cache: PathCache;
  private readonly gridSignature: string;
  private searches = 0;
  private cacheHits = 0;

  public constructor(rows: readonly (readonly number[])[], options: NavigationServiceOptions = {}) {
    this.grid = new NavigationGrid(rows, options.tileSize ?? 32, options.policy);
    this.pathfinder = new AStarPathfinder(this.grid);
    this.cache = new PathCache(options.cacheCapacity ?? 384);
    this.gridSignature = this.grid.signature();
  }

  public findPath(startWorld: NavPoint, goalWorld: NavPoint, options: PathSearchOptions = {}): NavigationPath {
    const start = this.grid.closestWalkable(this.grid.worldToCell(startWorld));
    const goal = this.grid.closestWalkable(this.grid.worldToCell(goalWorld));
    if (!start || !goal) return { points: [], reachedGoal: false, visited: 0, cost: Infinity };
    const key = this.cacheKey(start, goal, options);
    const cached = this.cache.get(key);
    if (cached) {
      this.cacheHits++;
      return cached;
    }
    this.searches++;
    const result = this.pathfinder.find(start, goal, options);
    const points = result.cells.map((cell) => this.grid.cellToWorld(cell));
    const path = { points, reachedGoal: result.reachedGoal, visited: result.visited, cost: result.cost };
    this.cache.set(key, path);
    return path;
  }

  public hasLineOfSight(startWorld: NavPoint, endWorld: NavPoint): boolean {
    return this.grid.worldLineOfSight(startWorld, endWorld);
  }

  public closestWalkableWorld(point: NavPoint): NavPoint | undefined {
    const cell = this.grid.closestWalkable(this.grid.worldToCell(point));
    return cell ? this.grid.cellToWorld(cell) : undefined;
  }

  public isWalkableWorld(point: NavPoint): boolean {
    return this.grid.isWalkable(this.grid.worldToCell(point));
  }

  public diagnostics(): { searches: number; cacheHits: number; cacheSize: number } {
    return { searches: this.searches, cacheHits: this.cacheHits, cacheSize: this.cache.size };
  }

  private cacheKey(start: NavCell, goal: NavCell, options: PathSearchOptions): string {
    return [
      this.gridSignature,
      cellKey(start),
      cellKey(goal),
      options.allowDiagonal === false ? '4' : '8',
      options.preventCornerCutting === false ? 'cut' : 'safe',
      options.smooth === false ? 'raw' : 'smooth',
    ].join('|');
  }
}

--- src/ai/behavior/EnemyBrain.ts ---
import { NavPoint, distance, squaredDistance } from '../navigation';
import { behaviorProfile } from './profiles';
import {
  AwarenessState,
  BrainDecision,
  BrainObservation,
  BrainSnapshot,
  EnemyBehaviorProfile,
  EnemyRole,
  copyPoint,
} from './types';

export class EnemyBrain {
  private profile: EnemyBehaviorProfile;
  private state: AwarenessState;
  private timeInState = 0;
  private alertness = 0;
  private unseenElapsed = Infinity;
  private memoryElapsed = Infinity;
  private patrolWaitElapsed = 0;
  private searchElapsed = 0;
  private patrolIndex = 0;
  private lastKnownTarget?: NavPoint;
  private readonly home: NavPoint;
  private patrol: NavPoint[];
  private damaged = false;
  private searchStep = 0;

  public constructor(
    role: EnemyRole,
    home: NavPoint,
    patrol: readonly NavPoint[] = [],
    overrides: Partial<EnemyBehaviorProfile> = {},
  ) {
    this.profile = behaviorProfile(role, overrides);
    this.home = { ...home };
    this.patrol = patrol.length > 0 ? patrol.map((point) => ({ ...point })) : [{ ...home }];
    this.state = this.patrol.length > 1 ? 'patrol' : 'idle';
  }

  public setPatrol(points: readonly NavPoint[]): void {
    this.patrol = points.length > 0 ? points.map((point) => ({ ...point })) : [{ ...this.home }];
    this.patrolIndex = Math.min(this.patrolIndex, this.patrol.length - 1);
  }

  public notifyDamaged(targetPosition?: NavPoint): void {
    this.damaged = true;
    this.alertness = 1;
    if (targetPosition) {
      this.lastKnownTarget = { ...targetPosition };
      this.memoryElapsed = 0;
    }
  }

  public update(observation: BrainObservation): BrainDecision {
    const delta = Math.max(0, Math.min(observation.delta, 250));
    this.timeInState += delta;
    this.memoryElapsed += delta;
    this.unseenElapsed += delta;
    this.alertness = Math.max(0, this.alertness - delta / Math.max(1, this.profile.memoryDuration));

    if (observation.targetVisible) {
      this.lastKnownTarget = { ...observation.target };
      this.memoryElapsed = 0;
      this.unseenElapsed = 0;
      this.alertness = Math.min(1, this.alertness + this.profile.aggression * 0.35 + 0.2);
    } else if (observation.targetAudible) {
      this.lastKnownTarget = { ...observation.target };
      this.memoryElapsed = 0;
      this.alertness = Math.min(1, this.alertness + 0.18);
    }

    if (this.damaged) {
      this.damaged = false;
      if (!this.lastKnownTarget) this.lastKnownTarget = { ...observation.target };
      this.transition('alert');
    }

    this.selectState(observation);
    return this.buildDecision(observation);
  }

  public snapshot(): BrainSnapshot {
    return {
      state: this.state,
      timeInState: this.timeInState,
      alertness: this.alertness,
      lastKnownTarget: copyPoint(this.lastKnownTarget),
      patrolIndex: this.patrolIndex,
    };
  }

  private selectState(observation: BrainObservation): void {
    const visible = observation.targetVisible;
    const inAttackBand = observation.distanceToTarget >= this.profile.attackMinimumRange
      && observation.distanceToTarget <= this.profile.attackMaximumRange;
    const tooClose = observation.distanceToTarget < this.profile.retreatRange;
    const leashed = distance(observation.self, this.home) > this.profile.leashRange;

    if (leashed && !visible && this.state !== 'return') {
      this.transition('return');
      return;
    }
    if (visible) {
      if (this.state === 'idle' || this.state === 'patrol' || this.state === 'return') {
        this.transition('alert');
        return;
      }
      if (this.state === 'alert' && this.timeInState < this.profile.alertDuration) return;
      if (inAttackBand || tooClose) this.transition('engage');
      else this.transition('chase');
      return;
    }
    if (observation.targetAudible && this.lastKnownTarget) {
      this.transition('investigate');
      return;
    }
    if (this.unseenElapsed <= this.profile.loseSightDelay && this.lastKnownTarget) {
      this.transition('chase');
      return;
    }
    if (this.lastKnownTarget && this.memoryElapsed <= this.profile.memoryDuration) {
      if (distance(observation.self, this.lastKnownTarget) > 22) this.transition('investigate');
      else this.transition('search');
      return;
    }
    if (this.state === 'search') {
      this.searchElapsed += observation.delta;
      if (this.searchElapsed < this.profile.searchDuration) return;
    }
    if (distance(observation.self, this.home) > 28) this.transition('return');
    else this.transition(this.patrol.length > 1 ? 'patrol' : 'idle');
  }

  private buildDecision(observation: BrainObservation): BrainDecision {
    let moveTarget: NavPoint | undefined;
    let wantsAttack = false;
    let wantsRetreat = false;
    switch (this.state) {
      case 'alert':
        moveTarget = undefined;
        break;
      case 'chase':
        moveTarget = copyPoint(observation.targetVisible ? observation.target : this.lastKnownTarget);
        break;
      case 'engage':
        wantsAttack = observation.targetVisible;
        wantsRetreat = observation.distanceToTarget < this.profile.retreatRange;
        if (!wantsAttack) moveTarget = copyPoint(this.lastKnownTarget);
        break;
      case 'investigate':
        moveTarget = copyPoint(this.lastKnownTarget);
        break;
      case 'search':
        moveTarget = this.searchTarget();
        break;
      case 'return':
        moveTarget = { ...this.home };
        if (distance(observation.self, this.home) <= 24) this.transition(this.patrol.length > 1 ? 'patrol' : 'idle');
        break;
      case 'patrol':
        moveTarget = this.patrolTarget(observation.self, observation.delta);
        break;
      case 'idle':
        moveTarget = undefined;
        break;
    }
    return {
      state: this.state,
      moveTarget,
      lookTarget: copyPoint(observation.targetVisible ? observation.target : this.lastKnownTarget),
      lastKnownTarget: copyPoint(this.lastKnownTarget),
      targetVisible: observation.targetVisible,
      wantsAttack,
      wantsRetreat,
      urgency: this.urgency(),
    };
  }

  private patrolTarget(self: NavPoint, delta: number): NavPoint | undefined {
    const target = this.patrol[this.patrolIndex];
    if (distance(self, target) > 18) {
      this.patrolWaitElapsed = 0;
      return { ...target };
    }
    this.patrolWaitElapsed += delta;
    if (this.patrolWaitElapsed < this.profile.patrolWait) return undefined;
    this.patrolWaitElapsed = 0;
    this.patrolIndex = (this.patrolIndex + 1) % this.patrol.length;
    return { ...this.patrol[this.patrolIndex] };
  }

  private searchTarget(): NavPoint | undefined {
    if (!this.lastKnownTarget) return undefined;
    const ring = 1 + Math.floor(this.searchStep / 8);
    const angle = (this.searchStep % 8) * Math.PI / 4;
    this.searchStep = (this.searchStep + 1) % 24;
    const radius = 24 + ring * 22;
    return {
      x: this.lastKnownTarget.x + Math.cos(angle) * radius,
      y: this.lastKnownTarget.y + Math.sin(angle) * radius,
    };
  }

  private urgency(): number {
    switch (this.state) {
      case 'engage': return 1;
      case 'chase': return 0.92;
      case 'alert': return 0.85;
      case 'investigate': return 0.68;
      case 'search': return 0.5;
      case 'return': return 0.42;
      case 'patrol': return 0.3;
      default: return 0;
    }
  }

  private transition(next: AwarenessState): void {
    if (next === this.state) return;
    this.state = next;
    this.timeInState = 0;
    if (next === 'search') {
      this.searchElapsed = 0;
      this.searchStep = 0;
    }
    if (next === 'idle' || next === 'patrol') {
      this.lastKnownTarget = undefined;
      this.memoryElapsed = Infinity;
      this.alertness = 0;
    }
  }
}

