    if (this.heroClass.primaryStyle === 'daggers' && heldMs < Player.ROGUE_THROW_THRESHOLD_MS) {
      this.executeAttack('P', 0, false);
    } else {
      this.executeAttack('P', charge, true);
    }
  }

