  private performUndo(): void {
    this.setStatus(this.model.undo() ? 'AlteraÃ§Ã£o desfeita.' : 'Nada para desfazer.');
    this.refresh();
  }

  private performRedo(): void {
    this.setStatus(this.model.redo() ? 'AlteraÃ§Ã£o refeita.' : 'Nada para refazer.');
