 374:       knight: { tint: 0xf5cf5b, damage: 40, attackCooldown: 900, duration: 1100, projectileTexture: 'proj_sword_wave', volleySize: 1, spread: 0, projectileScale: 2.4, piercing: 4 },
 375:       // Single nova per summon, like the knight's sword wave
 376:       mage: { tint: 0x62e1ff, damage: 24, attackCooldown: 900, duration: 700, projectileTexture: 'proj_magic_bolt', volleySize: 0, spread: 0, aoeRadius: 95, aoeDamage: 24 },
 377:       // Volley of many arrows in a wide fan
 378:       ranger: { tint: 0xc8e66b, damage: 12, attackCooldown: 650, duration: 6500, projectileTexture: 'proj_ranger_arrow', volleySize: 5, spread: 0.13, projectileScale: 0.85, piercing: 2 },
 379:       // Shadow clone: short-lived, strikes twice with fast daggers
 380:       rogue: { tint: 0xe84f75, damage: 16, attackCooldown: 420, duration: 700, projectileTexture: 'proj_rogue_dagger', volleySize: 2, spread: 0.2, projectileScale: 1.1 },
 381:     };
 382:     const config = { ...(configs[classId] ?? configs.knight) };
 383:     // 'empowered' (PPPP) makes a stronger, bigger, longer summon
 384:     if (variant === 'empowered') {
 385:       config.damage = Math.round(config.damage * 1.7);
 386:       config.aoeDamage = config.aoeDamage ? Math.round(config.aoeDamage * 1.7) : undefined;
