 416:   private calculatePlayerDamage(baseAmount: number, forcedType?: DamageType): number {
 417:     const classId = this.player.heroClass.id;
 418:     const damageType: DamageType = forcedType ?? (
 419:       classId === 'mage' ? 'arcane' : classId === 'rogue' ? 'shadow' : 'physical'
 420:     );
 421:     const progressionMultiplier = this.progression.snapshot().modifiers.damageMultiplier;
 422:     const damage = this.combatBridge.calculatePlayerDamage(
 423:       baseAmount * progressionMultiplier,
 424:       damageType,
 425:       this.comboManager.getDamageMultiplier(),
 426:     );
 427:     this.progression.recordDamageDealt(damage);
 428:     return damage;
