 507:   private spawnEnemiesAndItems(level: LevelDefinition): void {
 508:     // Build wave schedule: hand-authored waves if present, otherwise chunk by level
 509:     if (level.waves && level.waves.length > 0) {
 510:       this.waves = level.waves.map(w => ({ enemies: w.enemies }));
 511:     } else {
 512:       const sorted = [...level.enemies].sort((a, b) => a.level - b.level);
 513:       this.waves = [];
 514:       for (let i = 0; i < sorted.length; i += 8) {
 515:         this.waves.push({ enemies: sorted.slice(i, i + 8) });
 516:       }
 517:       const minibossSpots = [{ x: 25, y: 8 }, { x: 30, y: 9 }, { x: 34, y: 9 }];
 518:       const mb = minibossSpots[this.currentLevelIndex] ?? { x: 20, y: 8 };
 519:       this.waves.push({ enemies: [{ type: 'miniboss', x: mb.x, y: mb.y, level: 9 }] });
 520:     }
 521:     this.currentWaveIndex = 0;
 522:     this.waveDelayTimer = 0;
 523:     this.waveTransition = false;
 524:     // Wave 0 is spawned in create() once the HUD (banner text) exists.
 525: 
 526:     level.items.forEach(itm => {
 527:       // Keys already collected stay collected across revisits
 528:       if (itm.type === 'key') {
 529:         const keyId = `${this.currentLevelIndex}:${itm.x},${itm.y}`;
 530:         if (this.foundKeys.has(keyId)) return;
 531:       }
 532:       const px = itm.x * 32 + 16;
 533:       const py = itm.y * 32 + 16;
 534:       const isHealth = itm.type === 'potion' || itm.type === 'health_herb';
 535:       const isMagic = itm.type === 'mana_shard';
 536:       const isKey = itm.type === 'key';
 537:       const itemType = isHealth ? 'item_potion' : isMagic ? 'item_magic' : isKey ? 'item_key' : 'item_halo';
 538:       const textureKey = isMagic ? 'item_potion' : itemType;
 539:       const itemEntity = new Item(this, px, py, itemType, textureKey);
 540:       this.items.add(itemEntity);
 541:     });
 542:   }
