 255:   protected think(playerX: number, playerY: number, delta: number): BrainDecision {
 256:     const self = { x: this.x, y: this.y };
 257:     const target = { x: playerX, y: playerY };
 258:     this.lastPlayerPosition = target;
 259:     this.tacticalElapsed += Math.max(0, Math.min(delta, 250));
 260:     const targetDistance = Phaser.Math.Distance.Between(this.x, this.y, playerX, playerY);
 261:     if (!this.brain || !this.perception) {
 262:       return {
 263:         state: targetDistance < 400 ? 'chase' : 'idle',
 264:         moveTarget: targetDistance > 20 && targetDistance < 400 ? target : undefined,
 265:         lookTarget: target,
 266:         lastKnownTarget: target,
 267:         targetVisible: targetDistance < 400,
 268:         wantsAttack: targetDistance >= 36 && targetDistance <= 155,
 269:         wantsRetreat: false,
 270:         urgency: targetDistance < 400 ? 1 : 0,
 271:       };
