 274:     const sensed = this.perception.sense({
 275:       observer: self,
 276:       target,
 277:       facing: this.facing,
 278:       lineOfSight,
 279:       targetNoise: 1,
 280:     });
 281:     const decision = this.brain.update({
 282:       self,
 283:       target,
 284:       delta,
 285:       targetVisible: sensed.visible,
 286:       targetAudible: sensed.audible,
 287:       distanceToTarget: sensed.distance,
 288:     });
