   1: // src/entities/RangedEnemy.ts
   2: // Flying Archer angel enemy (Applaud) that shoots divine light arrows.
   3: 
   4: import { Enemy } from './Enemy';
   5: import Phaser from 'phaser';
   6: 
   7: export class RangedEnemy extends Enemy {
   8:   private shootCooldown: number = 0;
   9:   private projectileGroup?: Phaser.Physics.Arcade.Group;
  10:   private windupTimer = 0;
  11:   private shotCount = 0;
  12: 
  13:   constructor(scene: Phaser.Scene, x: number, y: number, projectileGroup?: Phaser.Physics.Arcade.Group) {
  14:     super(scene, x, y, 'enemy_ranged_anim');
  15:     this.projectileGroup = projectileGroup;
  16:     this.enemyRole = 'ranged';
  17:     this.enemyType = 'applaud';
  18:     this.speed = 90;
  19:     this.hp = 130;
  20:     this.maxHp = 130;
  21:     this.attackDamage = 10;
  22:     this.setDisplaySize(78, 69);
  23:     this.setSize(42, 56).setOffset(43, 46);
  24:   }
  25: 
  26:   public override updateEnemy(playerX: number, playerY: number, delta: number, speedMultiplier: number = 1): void {
  27:     if (!this.active || !this.body) return;
  28:     this.syncHealthBar();
  29: 
  30:     const dx = playerX - this.x;
  31:     const dy = playerY - this.y;
  32:     const dist = Math.sqrt(dx * dx + dy * dy);
  33:     const decision = this.think(playerX, playerY, delta);
  34: 
  35:     // Keep distance and shoot
  36:     if (dist < 1) {
  37:       this.setVelocity(0, 0);
  38:       this.updateMovementAnimation(false);
  39:     } else if (decision.wantsRetreat || (decision.targetVisible && dist < 180)) {
  40:       // Back away
  41:       if (this.windupTimer > 0) {
  42:         this.windupTimer = 0;
  43:         this.clearTint();
  44:       }
  45:       this.moveUsingNavigation(this.retreatTarget(playerX, playerY, 175), delta, this.speed * 1.15 * speedMultiplier);
  46:     } else if (decision.wantsAttack && decision.targetVisible) {
  47:       // Hold position and shoot
  48:       this.setVelocity(0, 0);
  49:       this.updateMovementAnimation(false);
  50:       this.shootCooldown -= delta;
  51:       if (this.shootCooldown <= 0 && this.windupTimer <= 0) {
  52:         // Telegraphed windup so the arrow shot is dodgeable
  53:         this.windupTimer = 380;
  54:         this.setTint(0xffee66);
  55:         this.playEnemyAction('attack');
  56:       }
  57:       if (this.windupTimer > 0) {
  58:         this.windupTimer -= delta;
  59:         if (this.windupTimer <= 0) {
  60:           this.clearTint();
  61:           this.shotCount++;
  62:           // Every 3rd shot is a spread of 3 arrows to control space
  63:           if (this.shotCount % 3 === 0) {
  64:             this.shootSpread(playerX, playerY);
  65:           } else {
  66:             this.shootArrow(playerX, playerY);
  67:           }
  68:           this.shootCooldown = 2000; // 2 sec cooldown
  69:         }
  70:       }
  71:     } else if (decision.moveTarget) {
  72:       // Reposition through the navigation graph until the target is visible
  73:       // and inside the ranged attack band.
  74:       if (this.windupTimer > 0) {
  75:         this.windupTimer = 0;
  76:         this.clearTint();
  77:       }
  78:       this.moveUsingNavigation(decision.moveTarget, delta, this.speed * speedMultiplier);
  79:     } else {
  80:       this.setVelocity(0, 0);
  81:       this.updateMovementAnimation(false);
  82:     }
  83:   }
  84: 
  85:   private spawnArrow(angle: number): void {
  86:     const arrow = this.scene.physics.add.sprite(this.x, this.y, 'proj_divine_arrow') as Phaser.Physics.Arcade.Sprite & { bulletDamage: number; baseVelX: number; baseVelY: number };
  87:     arrow.bulletDamage = this.attackDamage;
  88:     this.projectileGroup?.add(arrow);
  89:     arrow.setRotation(angle);
  90:     arrow.baseVelX = Math.cos(angle) * 250;
  91:     arrow.baseVelY = Math.sin(angle) * 250;
  92:     arrow.setVelocity(arrow.baseVelX, arrow.baseVelY);
  93:     this.scene.time.delayedCall(3000, () => {
  94:       if (arrow.active) arrow.destroy();
  95:     });
  96:   }
  97: 
  98:   private shootSpread(targetX: number, targetY: number): void {
  99:     const base = Phaser.Math.Angle.Between(this.x, this.y, targetX, targetY);
 100:     this.spawnArrow(base - 0.28);
 101:     this.spawnArrow(base);
 102:     this.spawnArrow(base + 0.28);
 103:   }
 104: 
 105:   private shootArrow(targetX: number, targetY: number): void {
 106:     const angle = Phaser.Math.Angle.Between(this.x, this.y, targetX, targetY);
 107:     this.spawnArrow(angle);
 108:   }
 109: }
