 118:   private handlePointerDown(pointer: Phaser.Input.Pointer, currentlyOver: Phaser.GameObjects.GameObject[]): void {
 119:     if (!this.combatInputEnabled || currentlyOver.length > 0) return;
 120:     this.aimAtPointer(pointer);
 121:     if (pointer.rightButtonDown()) {
 122:       // Right MB = Kick combo input (replaces the old special burst)
 123:       this.executeAttack('K');
 124:     }
 125:     else if (pointer.leftButtonDown()) {
 126:       if (this.heroClass.primaryStyle === 'arrow' || this.heroClass.primaryStyle === 'daggers') {
 127:         if (this.attackCooldown <= 0 && !this.isDodging) {
 128:           this.chargeStartedAt = this.scene.time.now;
 129:           this.updateBowChargePose();
 130:         }
 131:       } else {
 132:         this.executeAttack('P');
 133:       }
 134:     }
 135:   }
 136: 
 137:   private handlePointerUp(pointer: Phaser.Input.Pointer): void {
 138:     if (pointer.button !== 0) return;
 139:     if (pointer.button === 0 && this.heroClass.primaryStyle !== 'arrow' && this.heroClass.primaryStyle !== 'daggers') {
 140:       // Melee/orb already fired the punch on press
 141:       this.chargeStartedAt = null;
 142:       return;
 143:     }
 144:     if (this.chargeStartedAt === null) return;
 145:     const heldMs = this.scene.time.now - this.chargeStartedAt;
 146:     this.chargeStartedAt = null;
 147:     if (!this.combatInputEnabled || !this.active) return;
 148:     this.aimAtPointer(pointer);
 149:     const charge = Phaser.Math.Clamp(heldMs / Player.MAX_CHARGE_MS, 0, 1);
 150:     if (this.heroClass.primaryStyle === 'daggers' && heldMs < Player.ROGUE_THROW_THRESHOLD_MS) {
 151:       this.executeAttack('P', 0, false);
 152:     } else {
 153:       this.executeAttack('P', charge, true);
 154:     }
 155:   }
