 157:   public updatePlayer(_time: number, delta: number): void {
 158:     if (!this.active || !this.body) return;
 159:     if (!this.combatInputEnabled) this.chargeStartedAt = null;
 160:     this.aimAtPointer(this.scene.input.activePointer);
 161:     // Witch Time: attack cooldown drains faster and magic regenerates
 162:     this.attackCooldown = Math.max(0, this.attackCooldown - delta * (this.isWitchTimeActive ? 2.5 : 1));
 163:     if (this.isWitchTimeActive) this.addMagic(delta * 0.02);
 164:     this.dodgeCooldown = Math.max(0, this.dodgeCooldown - delta);
 165:     this.footstepEffectCooldown = Math.max(0, this.footstepEffectCooldown - delta);
 166:     this.comboInputLock = Math.max(0, this.comboInputLock - delta);
 167:     // Consume a buffered combo input once the lockout ends
 168:     if (this.comboInputLock <= 0 && this.bufferedInput !== null) {
 169:       const buffered = this.bufferedInput;
 170:       const bufferedAt = this.bufferedAt;
 171:       this.bufferedInput = null;
 172:       if (this.scene.time.now - bufferedAt <= 300) {
 173:         this.executeAttack(buffered);
 174:       }
 175:     }
 176:     if (this.isWitchTimeActive) {
 177:       this.witchTimeRemaining -= delta;
 178:       if (this.witchTimeRemaining <= 0) {
 179:         this.isWitchTimeActive = false;
 180:         this.clearTint();
 181:       }
 182:     }
 183:     if (this.comboSequence.length > 0) {
 184:       this.comboTimer += delta;
 185:       if (this.comboTimer > 2600) {
 186:         this.comboSequence = [];
 187:         this.comboTimer = 0;
 188:         this.comboWindowStart = null;
 189:       }
 190:     }
 191: 
 192:     let vx = 0;
 193:     let vy = 0;
 194:     if (this.cursors?.left.isDown || this.keyA?.isDown) vx--;
 195:     if (this.cursors?.right.isDown || this.keyD?.isDown) vx++;
 196:     if (this.cursors?.up.isDown || this.keyW?.isDown) vy--;
 197:     if (this.cursors?.down.isDown || this.keyS?.isDown) vy++;
 198:     if (vx !== 0 && vy !== 0) {
 199:       vx *= 0.7071;
 200:       vy *= 0.7071;
 201:     }
 202: 
 203:     if (this.keyDodge && Phaser.Input.Keyboard.JustDown(this.keyDodge) && !this.isDodging && this.dodgeCooldown <= 0) {
 204:       this.triggerDodge(vx, vy);
 205:     }
 206: 
 207:     if (this.isDodging) {
 208:       this.setVelocity(this.dodgeDirectionX * this.speed * 2.65, this.dodgeDirectionY * this.speed * 2.65);
 209:     } else {
 210:       this.setVelocity(vx * this.speed, vy * this.speed);
 211:     }
 212: 
 213:     if (!this.isDodging) {
 214:       this.faceMovement(this.heroClass.primaryStyle === 'arrow' ? this.facingX : vx);
 215:     }
 216:     // The archer uses one body for idle, movement and shooting. Swapping to the
 217:     // original sheet here changes the character's proportions between shots.
 218:     const drawingBow = this.updateBowChargePose();
 219:     if (!this.animationLocked && !drawingBow) {
 220:       if (vx !== 0 || vy !== 0) {
 221:         // Player and enemies now use the same animation path. The artwork
 222:         // already contains four distinct contact poses, so no synthetic sway,
 223:         // rotation or squash is applied on top of the actual sprite frames.
 224:         this.play(`${this.animationPrefix}_walk`, true);
 225:         this.setScale(this.baseScaleX, this.baseScaleY);
 226:         this.setAngle(0);
 227:       } else {
 228:         this.resetMovementPose();
 229:       }
 230:     }
 231:     if (!this.animationLocked && !this.isDodging && (vx !== 0 || vy !== 0) && this.footstepEffectCooldown <= 0) {
 232:       this.spawnFootstepDust();
 233:       this.footstepEffectCooldown = 155;
 234:     }
 235:     if (this.keyAttack && Phaser.Input.Keyboard.JustDown(this.keyAttack)) this.usePrimaryWeapon();
 236:     if (this.keyKickButton && Phaser.Input.Keyboard.JustDown(this.keyKickButton)) this.executeAttack('K');
 237:   }
