 239:   private faceMovement(directionX: number): void {
 240:     if (Math.abs(directionX) < 0.001) return;
 241:     const originallyFacesRight = this.heroClass.spriteFacing === 'right';
 242:     this.setFlipX(originallyFacesRight ? directionX < 0 : directionX > 0);
