 245:   private updateBowChargePose(): boolean {
 246:     if (this.heroClass.primaryStyle !== 'arrow') return false;
 247:     const charging = this.isChargingAttack();
 248:     const releasing = this.bowReleaseUntil > 0 && this.scene.time.now < this.bowReleaseUntil;
 249:     if ((!charging && !releasing) || this.isDodging || this.animationLocked) {
 250:       this.archerBow?.hide();
 251:       return false;
 252:     }
 253:     // Keep the same body and scale even before drawing and after releasing.
 254:     // Only the arms, string and arrow change during an ordinary attack.
 255:     const frame = releasing ? 6 : this.getChargeRatio() < 0.45 ? 4 : 5;
 256:     const angle = releasing ? this.bowReleaseAngle : Math.atan2(this.facingY, this.facingX);
 257:     this.stop();
 258:     this.setTexture(this.archerBow?.bodyKey ?? this.animationPrefix, this.archerBow ? undefined : frame);
 259:     this.setScale(this.baseScaleX, this.baseScaleY);
 260:     this.setAngle(0);
 261:     this.faceMovement(Math.cos(angle));
 262:     this.archerBow?.setPose(frame - 4, angle, releasing ? 0 : this.getChargeRatio());
 263:     this.syncArcherBow();
 264:     return true;
 265:   }
