 296:   /** Bayonetta-style combat input: 'P' = punch (left MB), 'K' = kick (right MB). */
 297:   public executeAttack(input: 'P' | 'K', charge = 0, throwDagger = false): void {
 298:     // Animation lockout: an attack must play out before the next one can start.
 299:     // Early presses are buffered so combos can be chained fluidly.
 300:     if (this.comboInputLock > 0) {
 301:       this.bufferedInput = input;
 302:       this.bufferedAt = this.scene.time.now;
 303:       return;
 304:     }
 305: 
 306:     // Combo sequence expires: finishers must be executed within a tight window
 307:     if (this.comboSequence.length > 0 && this.comboWindowStart !== null &&
 308:         this.scene.time.now - this.comboWindowStart > 2600) {
 309:       this.comboSequence = [];
 310:       this.comboWindowStart = null;
 311:     }
 312:     if (this.comboSequence.length === 0) {
 313:       this.comboWindowStart = this.scene.time.now;
 314:     }
 315: 
 316:     this.comboSequence.push(input);
 317:     this.comboTimer = 0;
 318: 
 319:     // Combo finishers: last three/four inputs match a known pattern within the window
 320:     const seqStr = this.comboSequence.join('');
 321:     const last3 = seqStr.slice(-3);
 322:     const last4 = seqStr.slice(-4);
 323:     const WITCH_COMBOS = ['PPK', 'KPK', 'PKP', 'KKP', 'PKK'];
 324: 
 325:     // Empowered summon finisher: four punches
 326:     if (this.comboSequence.length >= 4 && last4 === 'PPPP') {
 327:       this.comboSequence = [];
 328:       this.comboWindowStart = null;
 329:       this.comboInputLock = 620;
 330:       if (this.magic >= this.heroClass.magicCost) {
 331:         this.magic -= this.heroClass.magicCost;
 332:         this.scene.events.emit('playerSummon', this.x, this.y, this.heroClass.id, 'empowered');
 333:       }
 334:       SoundManager.playWickedWeave();
 335:       this.spawnSpecialRing(this.heroClass.accentColor);
 336:       this.performPrimaryAttack(0, false, false);
 337:       return;
 338:     }
 339: 
 340:     // Witch Combo finisher: last three inputs match a known pattern within the window
 341:     if (this.comboSequence.length >= 3 && WITCH_COMBOS.includes(last3)) {
 342:       this.comboSequence = [];
 343:       this.comboWindowStart = null;
 344:       this.comboInputLock = 620;
 345:       if (this.magic >= this.heroClass.magicCost) {
 346:         this.magic -= this.heroClass.magicCost;
 347:         this.scene.events.emit('playerSummon', this.x, this.y, this.heroClass.id, 'normal');
 348:       }
 349:       SoundManager.playWickedWeave();
 350:       this.spawnSpecialRing(this.heroClass.accentColor);
 351:       // The finisher hit still goes out — it is not a cancel
 352:       if (input === 'K') this.performPrimaryAttack(0, false, true);
 353:       else this.performPrimaryAttack(charge, throwDagger, false);
 354:       return;
 355:     }
 356: 
 357:     this.comboInputLock = input === 'P' ? 220 : 330;
 358:     if (input === 'P') {
 359:       this.performPrimaryAttack(charge, throwDagger, false);
 360:     } else {
 361:       this.performPrimaryAttack(0, false, true);
 362:     }
 363:   }
