 141:     this.physics.world.resume();
 142:     // 1. Generate all vector textures
 143:     TextureGenerator.generateAllTextures(this);
 144: 
 145:     // 2. Create physics groups
 146:     this.wallTiles = this.physics.add.staticGroup();
 147:     this.stairTiles = this.physics.add.staticGroup();
 148:     this.enemies = this.physics.add.group();
 149:     this.items = this.physics.add.group();
 150:     this.bullets = this.physics.add.group();
 151:     this.enemyBullets = this.physics.add.group();
 152: 
 153:     // 3. Build level map
 154:     this.currentLevel = this.allLevels[this.currentLevelIndex];
 155:     this.buildMapFromDefinition(this.currentLevel);
 156:     this.navigation = new NavigationService(this.currentLevel.tileMap, { tileSize: 32 });
 157:     this.progression = new ProgressionService();
 158: 
 159:     // 4. Create Player
 160:     const spawn = this.findSpawnPoint(this.currentLevel);
 161:     const appearance = loadAppearance();
 162:     const heroClass = getPlayerClass(appearance.classId);
 163:     this.player = new Player(this, spawn.x, spawn.y, getCharacterAnimationKey(appearance), heroClass);
 164:     this.player.bulletGroup = this.bullets;
 165:     this.simulationBridge = new GameSimulationBridge({
 166:       classId: appearance.classId,
 167:       section: this.currentLevel.name,
 168:     });
 169:     this.combatBridge = new GameCombatBridge({
 170:       classDefinition: heroClass,
 171:       seed: `${this.currentLevel.id}:${appearance.classId}`,
 172:     });
 173:     this.simulationBridge.synchronizePlayer({
 174:       x: this.player.x,
 175:       y: this.player.y,
 176:       health: this.player.hp,
 177:       maximumHealth: this.player.maxHp,
 178:       mana: this.player.magic,
 179:       maximumMana: this.player.maxMagic,
 180:     });
 181:     this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
 182:       this.simulationBridge.dispose();
 183:       this.combatBridge.dispose();
 184:     });
 185:     this.cameras.main.startFollow(this.player, true, 0.1, 0.1);
 186:     const worldWidth = this.currentLevel.tileMap[0].length * 32;
 187:     const worldHeight = this.currentLevel.tileMap.length * 32;
 188:     this.cameras.main.setBounds(0, 0, worldWidth, worldHeight);
 189:     this.physics.world.setBounds(0, 0, worldWidth, worldHeight);
 190: 
 191:     // 5. Spawn enemies and items
 192:     this.spawnEnemiesAndItems(this.currentLevel);
 193: 
 194:     // 6. Setup all colliders
 195:     this.setupColliders();
 196: 
 197:     // 7. Witch Time FX Overlay
 198:     const width = this.cameras.main.width;
 199:     const height = this.cameras.main.height;
 200:     this.witchTimeOverlay = this.add.rectangle(width / 2, height / 2, width, height, 0x110033, 0.4);
 201:     this.witchTimeOverlay.setScrollFactor(0);
 202:     this.witchTimeOverlay.setDepth(900);
 203:     this.witchTimeOverlay.setVisible(false);
 204: 
 205:     // 8. Key bindings
 206:     this.shopUI = new ShopUI(this, this.player);
 207:     if (this.input && this.input.keyboard) {
 208:       this.keyShop = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.B);
 209:       this.keyMenu = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.ESC);
 210:     }
 211: 
 212:     // 9. HUD & Chapter Title
 213:     this.createHUD();
 214:     this.comboManager = new ComboManager(this, this.comboHudText, () => this.player.extendComboWindow());
 215:     this.spawnWave(0);
 216:     this.events.off('enemyDropHalo');
 217:     this.events.on('enemyDropHalo', (x: number, y: number) => {
 218:       const halo = new Item(this, x, y, 'item_halo', 'item_halo');
 219:       this.items.add(halo);
 220:     });
 221:     this.events.off('enemyDefeated');
 222:     this.events.on('enemyDefeated', (defeat: EnemyDefeatProgress) => {
 223:       const update = this.progression.recordEnemyDefeat(defeat);
 224:       this.player.addHalos(update.currencyAwarded);
 225:       if (update.levelsGained > 0) {
 226:         this.levelBannerText.setText('NÍVEL ' + update.currentLevel + '!  +' + update.skillPointsAwarded + ' PONTO DE HABILIDADE');
 227:         this.levelBannerText.setVisible(true);
 228:         this.time.delayedCall(1500, () => {
 229:           if (!this.levelClearedBannerShowing) this.levelBannerText.setVisible(false);
 230:         });
 231:       }
 232:     });
 233:     this.events.off('enemyMeleeStrike');
 234:     this.events.off('playerSummon');
 235:     this.events.off('enemyShockwave');
 236:     this.events.off('summonNova');
 237:     this.events.on('summonNova', (x: number, y: number, dmg: number, radius: number) => {
 238:       this.enemies.getChildren().forEach(e => {
 239:         const enemy = e as Enemy;
 240:         if (enemy.active && Phaser.Math.Distance.Between(x, y, enemy.x, enemy.y) < radius) {
 241:           enemy.takeDamage(this.calculatePlayerDamage(dmg));
 242:           this.comboManager.registerHit();
 243:         }
 244:       });
 245:     });
 246:     this.events.on('enemyMeleeStrike', (dmg: number) => {
 247:       if (this.playerDamageCooldown <= 0 || this.player.isDodging) this.damagePlayer(dmg);
 248:     });
 249:     this.events.on('playerSummon', (x: number, y: number, classId: string, variant?: string) => this.spawnSummon(x, y, classId, variant));
 250:     this.events.on('enemyShockwave', (x: number, y: number, dmg: number) => {
 251:       if (Phaser.Math.Distance.Between(this.player.x, this.player.y, x, y) < 95) {
 252:         this.damagePlayer(dmg);
 253:       }
 254:     });
 255:     this.showChapterTitle(this.currentLevel.name);
 256:     this.createAimReticle();
 257:     this.arrowChargeBar = this.add.graphics().setDepth(30).setVisible(false);
 258:     if (loadSettings().showControls && !this.skipControlsGuide) this.showControlsGuide();
 259:   }
