 641:   private transitionToSection(exit: { to: number; spawnX: number; spawnY: number }): void {
 642:     if (this.isTransitioning) return;
 643:     this.isTransitioning = true;
 644:     this.cameras.main.flash(500, 255, 215, 0);
 645:     SoundManager.playWitchTimeActivate();
 646: 
 647:     this.time.delayedCall(400, () => {
 648:       const previousSection = this.currentLevel.name;
 649:       this.currentLevelIndex = exit.to;
 650:       this.currentLevel = this.allLevels[this.currentLevelIndex];
 651:       this.simulationBridge.recordRoomEntered(this.currentLevel.name, previousSection);
 652: 
 653:       this.floorImages.forEach(img => img.destroy());
 654:       this.floorImages = [];
 655:       this.enemies.clear(true, true);
 656:       this.items.clear(true, true);
 657:       this.bullets.clear(true, true);
 658:       this.enemyBullets.clear(true, true);
 659:       this.wallTiles.clear(true, true);
 660:       this.stairTiles.clear(true, true);
 661:       this.pendingExitTiles = [];
 662:       this.exitsRevealed = false;
 663:       this.summons.forEach(s => s.destroy());
 664:       this.summons = [];
 665: 
 666:       this.buildMapFromDefinition(this.currentLevel);
 667:       this.navigation = new NavigationService(this.currentLevel.tileMap, { tileSize: 32 });
 668:       this.spawnEnemiesAndItems(this.currentLevel);
 669:       this.spawnWave(0);
 670: 
 671:       this.player.setPosition(exit.spawnX * 32 + 16, exit.spawnY * 32 + 16);
 672:       this.player.setVelocity(0, 0);
 673:       this.player.setActive(true);
 674:       this.player.setVisible(true);
 675:       this.player.setAlpha(1);
 676:       this.player.resetResourcesForNextStage();
 677: 
 678:       // Rebuild camera/world bounds for the new section
 679:       const worldWidth = this.currentLevel.tileMap[0].length * 32;
 680:       const worldHeight = this.currentLevel.tileMap.length * 32;
 681:       this.cameras.main.setBounds(0, 0, worldWidth, worldHeight);
 682:       this.physics.world.setBounds(0, 0, worldWidth, worldHeight);
