 153:   public updateEnemy(playerX: number, playerY: number, _delta: number, speedMultiplier: number = 1): void {
 154:     if (!this.active || !this.body || this.dying) return;
 155:     this.syncHealthBar();
 156:     this.attackAnimationCooldown = Math.max(0, this.attackAnimationCooldown - _delta);
 157:     this.strikeCooldown = Math.max(0, this.strikeCooldown - _delta);
 158:     this.shockwaveCooldown = Math.max(0, this.shockwaveCooldown - _delta);
 159: 
 160:     const dx = playerX - this.x;
 161:     const dy = playerY - this.y;
 162:     const dist = Math.sqrt(dx * dx + dy * dy);
 163:     const decision = this.think(playerX, playerY, _delta);
 164: 
 165:     // Telegraph: flash red and pause before the lunge so the player can dodge
 166:     if (this.strikeState === 'telegraph') {
 167:       this.strikeTimer -= _delta;
 168:       this.setVelocity(0, 0);
 169:       this.updateMovementAnimation(false);
 170:       if (this.strikeTimer <= 0) {
 171:         this.strikeState = 'lunge';
 172:         this.strikeTimer = 300;
 173:         this.strikeHitDone = false;
 174:         if (dist > 1) {
 175:           this.strikeDirX = dx / dist;
 176:           this.strikeDirY = dy / dist;
 177:         }
 178:         this.clearTint();
 179:         this.playEnemyAction('attack');
 180:       }
 181:       return;
 182:     }
 183: 
 184:     // Lunge: fast, committed burst — dodging through it triggers Witch Time
 185:     if (this.strikeState === 'lunge') {
 186:       this.strikeTimer -= _delta;
 187:       this.setVelocity(this.strikeDirX * 430 * speedMultiplier, this.strikeDirY * 430 * speedMultiplier);
 188:       if (!this.strikeHitDone && dist < 38) {
 189:         this.strikeHitDone = true;
 190:         this.scene.events.emit('enemyMeleeStrike', this.attackDamage);
 191:       }
 192:       if (this.strikeTimer <= 0) {
 193:         this.strikeState = 'recover';
 194:         this.strikeTimer = 420;
 195:         this.setVelocity(0, 0);
 196:       }
 197:       return;
 198:     }
 199: 
 200:     if (this.strikeState === 'recover') {
 201:       this.strikeTimer -= _delta;
 202:       this.setVelocity(0, 0);
 203:       this.updateMovementAnimation(false);
 204:       if (this.strikeTimer <= 0) {
 205:         this.strikeState = 'none';
 206:         this.strikeCooldown = 1400;
 207:       }
 208:       return;
 209:     }
 210: 
 211:     if (decision.state !== 'idle' && decision.state !== 'patrol' && decision.targetVisible) {
 212:       // Second move: radial shockwave when the player presses in close
 213:       if (dist < 80 && this.shockwaveCooldown <= 0 && this.strikeState === 'none') {
 214:         this.shockwaveCooldown = 3200;
 215:         this.setVelocity(0, 0);
 216:         this.playEnemyAction('attack');
 217:         const ring = this.scene.add.circle(this.x, this.y, 24, 0xff8800, 0.25)
 218:           .setStrokeStyle(5, 0xff5500, 0.9)
 219:           .setDepth(15);
 220:         this.scene.tweens.add({ targets: ring, alpha: 0, scaleX: 4, scaleY: 4, duration: 420, onComplete: () => ring.destroy() });
 221:         this.scene.events.emit('enemyShockwave', this.x, this.y, this.attackDamage);
 222:         return;
 223:       }
 224:       // Start a telegraphed strike when in range
 225:       if (decision.wantsAttack && dist < 150 && dist > 40 && this.strikeCooldown <= 0) {
 226:         this.strikeState = 'telegraph';
 227:         this.strikeTimer = 550;
 228:         this.setTint(0xff3333);
 229:         this.setVelocity(0, 0);
 230:         this.updateMovementAnimation(false);
 231:         return;
 232:       }
 233:     }
 234: 
 235:     if (decision.moveTarget) {
 236:       this.moveUsingNavigation(decision.moveTarget, _delta, this.speed * speedMultiplier);
 237:     } else {
 238:       this.setVelocity(0, 0);
 239:       this.updateMovementAnimation(false);
 240:       if (decision.wantsAttack && dist <= 40 && this.attackAnimationCooldown <= 0) {
 241:         this.playEnemyAction('attack');
 242:         this.attackAnimationCooldown = 850;
 243:       }
 244:     }
 245:   }
