 313:   protected moveUsingNavigation(target: NavPoint, delta: number, maximumSpeed: number): void {
 314:     let velocity: NavPoint;
 315:     const tacticalSpeed = this.generatedDecision?.speedScale ?? 1;
 316:     maximumSpeed *= tacticalSpeed;
 317:     if (this.navigationAgent) {
 318:       velocity = this.navigationAgent.step({ x: this.x, y: this.y }, target, maximumSpeed, delta).velocity;
 319:     } else {
 320:       const dx = target.x - this.x;
 321:       const dy = target.y - this.y;
 322:       const length = Math.hypot(dx, dy);
 323:       velocity = length > 0 ? { x: dx / length * maximumSpeed, y: dy / length * maximumSpeed } : { x: 0, y: 0 };
 324:     }
 325:     const avoidance = separation({ x: this.x, y: this.y }, this.crowdNeighbors, 46, 1);
 326:     const separationScale = this.generatedDecision?.separationScale ?? 1;
 327:     const avoidanceWeight = (this.enemyRole === 'boss' ? 0.15 : 0.42) * separationScale;
 328:     velocity = blendVelocity(velocity, avoidance, avoidanceWeight);
 329:     this.setVelocity(velocity.x, velocity.y);
 330:     if (Math.hypot(velocity.x, velocity.y) > 1) {
 331:       this.facing = { x: velocity.x, y: velocity.y };
 332:       this.updateMovementAnimation(true);
 333:     } else {
 334:       this.updateMovementAnimation(false);
 335:     }
 336:   }
