 338:   protected retreatTarget(playerX: number, playerY: number, distanceToCreate = 150): NavPoint {
 339:     if (this.tacticalPositioning) {
 340:       return this.tacticalPositioning.retreatFrom(
 341:         { x: this.x, y: this.y },
 342:         { x: playerX, y: playerY },
 343:         distanceToCreate,
 344:       );
 345:     }
 346:     const dx = this.x - playerX;
 347:     const dy = this.y - playerY;
 348:     const length = Math.hypot(dx, dy) || 1;
 349:     return { x: this.x + dx / length * distanceToCreate, y: this.y + dy / length * distanceToCreate };
 350:   }
