 397:   private damagePlayer(amount: number): void {
 398:     const healthBeforeDamage = this.player.hp;
 399:     this.player.takeDamage(amount);
 400:     const appliedDamage = Math.max(0, healthBeforeDamage - this.player.hp);
 401:     if (appliedDamage > 0) {
 402:       this.simulationBridge.recordDamage(appliedDamage);
 403:       this.progression.recordDamageTaken(appliedDamage);
 404:     }
 405:     this.playerDamageCooldown = 500;
 406:     if (this.player.hp <= 0 && !this.isTransitioning) {
 407:       this.isTransitioning = true;
 408:       this.player.setVelocity(0, 0);
 409:       this.player.setActive(false);
 410:       this.levelBannerText.setText('GAME OVER');
 411:       this.levelBannerText.setVisible(true);
 412:       this.time.delayedCall(1500, () => this.scene.restart({ skipControls: true }));
 413:     }
