263:     this.physics.add.collider(this.player, this.wallTiles);
264:     // Enemies vs Walls
265:     this.physics.add.collider(this.enemies, this.wallTiles);
266: 
267:     // Player vs Enemy: dodging through an enemy damages it (Witch Arts).
268:     // Contact itself deals NO damage — players are only hurt by telegraphed
269:     // attacks (lunge, shockwave, bullets), so camping inside an enemy is safe.
270:     this.physics.add.overlap(this.player, this.enemies, (_playerObj, enemyObj) => {
271:       const enemy = enemyObj as Enemy;
272:       if (this.player.isDodging) {
273:         if (this.player.dodgeAttackId !== this.lastHandledDodgeAttack) {
274:           this.lastHandledDodgeAttack = this.player.dodgeAttackId;
275:           this.dodgeHitTargets.clear();
276:         }
277:         if (!this.dodgeHitTargets.has(enemy)) {
278:           this.dodgeHitTargets.add(enemy);
279:           enemy.takeDamage(this.calculatePlayerDamage(this.player.getDodgeDamage(), 'shadow'));
280:           this.comboManager.registerHit();
281:         }
282:         return;
283:       }
284:       // No contact damage — enemies can overlap the player freely without hurting them.
285:     });
286: 
287:     // Player vs Item Pickups
288:     this.physics.add.overlap(this.player, this.items, (_playerObj, itemObj) => {
289:       const itm = itemObj as Item;
290:       this.simulationBridge.recordItem(itm.itemType);
291:       this.progression.recordItemCollected(itm.itemType);
292:       if (itm.itemType === 'item_halo') {
293:         this.player.addHalos(100);
294:       } else if (itm.itemType === 'item_potion') {
295:         this.player.heal(40);
296:       } else if (itm.itemType === 'item_magic') {
297:         this.player.addMagic(25);
298:       } else if (itm.itemType === 'item_key') {
299:         const keyId = `${this.currentLevelIndex}:${Math.floor(itm.x / 32)},${Math.floor(itm.y / 32)}`;
300:         this.foundKeys.add(keyId);
301:         this.levelBannerText.setText('EMBOSCADA! Defenda-se!');
302:         this.levelBannerText.setVisible(true);
303:         this.time.delayedCall(1200, () => this.levelBannerText.setVisible(false));
304:         (this.currentLevel.ambush ?? []).forEach(e => this.spawnSingleEnemy(e));
305:       }
306:       itm.destroy();
307:     });
308: 
309:     // Player vs Section Doors → travel between sections
310:     this.physics.add.overlap(this.player, this.stairTiles, (_playerObj, doorObj) => {
311:       if (this.isTransitioning) return;
312:       // Doors are sealed while a wave is active — finish the fight first
313:       if (this.enemies.countActive(true) > 0 || this.waveTransition) {
314:         if (!this.doorSealNotice || this.time.now - this.doorSealNotice > 2000) {
315:           this.doorSealNotice = this.time.now;
316:           this.levelBannerText.setText('PORTAS SELADAS! Termine o combate.');
317:           this.levelBannerText.setVisible(true);
318:           this.time.delayedCall(1200, () => this.levelBannerText.setVisible(false));
319:         }
320:         return;
321:       }
322:       // Stairs/doors act as the level portal — only open once the section is cleared
323:       const wavesCleared = this.currentWaveIndex >= this.waves.length - 1 && this.enemies.countActive(true) === 0 && !this.waveTransition;
324:       if (!wavesCleared) {
325:         if (!this.doorSealNotice || this.time.now - this.doorSealNotice > 2000) {
326:           this.doorSealNotice = this.time.now;
327:           this.levelBannerText.setText('PORTAL BLOQUEADO! Elimine a horda.');
328:           this.levelBannerText.setVisible(true);
329:           this.time.delayedCall(1200, () => this.levelBannerText.setVisible(false));
330:         }
331:         return;
332:       }
333:       this.advanceToNextLevel();
334:     });
335: 
336:     // Bullets vs Enemies → ranged damage
337:     this.physics.add.overlap(this.bullets, this.enemies, (bulletObj, enemyObj) => {
338:       const bullet = bulletObj as Phaser.Physics.Arcade.Sprite;
339:       const enemy = enemyObj as Enemy;
340:       const combatBullet = bullet as CombatProjectile;
341:       if (combatBullet.hitTargets?.has(enemy)) return;
