269:     // attacks (lunge, shockwave, bullets), so camping inside an enemy is safe.
270:     this.physics.add.overlap(this.player, this.enemies, (_playerObj, enemyObj) => {
271:       const enemy = enemyObj as Enemy;
272:       if (this.player.isDodging) {
