291:       this.progression.recordItemCollected(itm.itemType);
292:       if (itm.itemType === 'item_halo') {
293:         this.player.addHalos(100);
294:       } else if (itm.itemType === 'item_potion') {
295:         this.player.heal(40);
296:       } else if (itm.itemType === 'item_magic') {
297:         this.player.addMagic(25);
298:       } else if (itm.itemType === 'item_key') {
299:         const keyId = `${this.currentLevelIndex}:${Math.floor(itm.x / 32)},${Math.floor(itm.y / 32)}`;
300:         this.foundKeys.add(keyId);
301:         this.levelBannerText.setText('EMBOSCADA! Defenda-se!');
