323:       const wavesCleared = this.currentWaveIndex >= this.waves.length - 1 && this.enemies.countActive(true) === 0 && !this.waveTransition;
324:       if (!wavesCleared) {
325:         if (!this.doorSealNotice || this.time.now - this.doorSealNotice > 2000) {
