309:     // Player vs Section Doors → travel between sections
310:     this.physics.add.overlap(this.player, this.stairTiles, (_playerObj, doorObj) => {
311:       if (this.isTransitioning) return;
312:       // Doors are sealed while a wave is active — finish the fight first
313:       if (this.enemies.countActive(true) > 0 || this.waveTransition) {
314:         if (!this.doorSealNotice || this.time.now - this.doorSealNotice > 2000) {
315:           this.doorSealNotice = this.time.now;
