321:       }
322:       // Stairs/doors act as the level portal — only open once the section is cleared
323:       const wavesCleared = this.currentWaveIndex >= this.waves.length - 1 && this.enemies.countActive(true) === 0 && !this.waveTransition;
324:       if (!wavesCleared) {
325:         if (!this.doorSealNotice || this.time.now - this.doorSealNotice > 2000) {
326:           this.doorSealNotice = this.time.now;
327:           this.levelBannerText.setText('PORTAL BLOQUEADO! Elimine a horda.');
