   5: 
   6: export class Item extends Phaser.Physics.Arcade.Sprite {
   7:   public itemType: string;
   8: 
   9:   constructor(scene: Phaser.Scene, x: number, y: number, itemType: string = 'item_halo', textureKey: string = itemType) {
  10:     super(scene, x, y, textureKey);
