 430: 
 431:   /** Find tile value 8 (spawn point) in the level map */
 432:   private findSpawnPoint(level: LevelDefinition): { x: number; y: number } {
 433:     const map = level.tileMap;
 434:     for (let r = 0; r < map.length; r++) {
 435:       for (let c = 0; c < map[r].length; c++) {
 436:         if (map[r][c] === 8) {
 437:           return { x: c * 32 + 16, y: r * 32 + 16 };
 438:         }
 439:       }
 440:     }
 441:     return { x: 120, y: 120 }; // fallback
 442:   }
 443: 
 444:   private buildMapFromDefinition(level: LevelDefinition): void {
 445:     const map = level.tileMap;
 446:     for (let r = 0; r < map.length; r++) {
 447:       for (let c = 0; c < map[r].length; c++) {
 448:         const tileVal = map[r][c];
 449:         const posX = c * 32 + 16;
 450:         const posY = r * 32 + 16;
 451: 
 452:         // Base Floor
 453:         const floorImg = this.add.image(posX, posY, 'tile_floor');
 454:         this.floorImages.push(floorImg);
 455: 
 456:         if (tileVal === 1) {
 457:           this.wallTiles.create(posX, posY, 'tile_wall');
 458:         } else if (tileVal === 2) {
 459:           this.wallTiles.create(posX, posY, 'tile_pillar');
 460:         } else if (tileVal === 4) {
 461:           const lava = this.add.image(posX, posY, 'tile_lava');
 462:           this.floorImages.push(lava);
 463:         } else if (tileVal === 5) {
 464:           // The tunnel is intentionally absent until the final enemy dies.
 465:           // Store its position without creating a visible/interactive sprite.
 466:           this.pendingExitTiles.push({ x: posX, y: posY });
 467:         }
 468:       }
 469:     }
 470:   }
 471: 
 472:   private spawnSingleEnemy(e: EnemyPlacement): void {
 473:     const px = e.x * 32 + 16;
 474:     const py = e.y * 32 + 16;
 475:     let enemy: Enemy;
 476:     if (e.type === 'ranged' || e.type === 'applaud') {
 477:       enemy = new RangedEnemy(this, px, py, this.enemyBullets);
 478:     } else if (e.type === 'boss' || e.type === 'fortitudo') {
 479:       enemy = new BossEnemy(this, px, py, 'Fortitudo');
 480:     } else if (e.type === 'miniboss') {
 481:       enemy = new BossEnemy(this, px, py, 'Sevido', 'boss_guardian_anim', 700, 0.6);
 482:     } else {
 483:       enemy = new Enemy(this, px, py, 'enemy_melee_anim');
 484:     }
 485:     const patrol = (e.patrol ?? []).map((point) => ({ x: point.x * 32 + 16, y: point.y * 32 + 16 }));
 486:     enemy.configureAI(this.navigation, patrol);
 487:     enemy.configureProgression(Math.max(e.level, this.currentLevel.difficulty));
 488:     this.enemies.add(enemy);
 489:   }
 490: 
 491:   private spawnWave(index: number): void {
 492:     const wave = this.waves[index];
 493:     if (!wave) return;
 494:     wave.enemies.forEach(e => this.spawnSingleEnemy(e));
 495:     this.simulationBridge.recordWaveStarted(this.currentLevel.name, index + 1, wave.enemies.length);
 496:     if (this.levelBannerText) {
 497:       this.levelBannerText.setText(`ONDA ${index + 1} / ${this.waves.length}`);
 498:       this.levelBannerText.setVisible(true);
 499:       this.time.delayedCall(1400, () => {
 500:         if (!this.levelClearedBannerShowing && this.enemies.countActive(true) > 0) {
 501:           this.levelBannerText.setVisible(false);
 502:         }
 503:       });
 504:     }
 505:   }
