    $null = $registro.AppendLine("- Sessão bruta: [$($prompt.Sessao)](sessoes/$($prompt.Sessao))")
    if ($prompt.Anexos -gt 0) {
        $rotulo = if ($prompt.Anexos -eq 1) { 'anexo' } else { 'anexos' }
        $null = $registro.AppendLine("- Anexos registrados no JSONL: $($prompt.Anexos) $rotulo")
    }
    $null = $registro.AppendLine()
    $null = $registro.AppendLine("$cerca" + 'text')
    $null = $registro.Append($prompt.Texto)
    if (-not $prompt.Texto.EndsWith("`n")) {
        $null = $registro.AppendLine()
    }
    $null = $registro.AppendLine($cerca)
    $null = $registro.AppendLine()
}

